-- =====================================================================
-- Migration 005: Notifications table
-- =====================================================================
-- Implements sections 27-28 (Notifications). Notifications are
-- generated by backend business logic (e.g. after a hazard is
-- verified) and stored directly in PostgreSQL — no email/SMS in this
-- phase, per the brief.
-- =====================================================================

CREATE TYPE notification_type AS ENUM (
    'hazard_submitted',
    'hazard_verified',
    'hazard_rejected',
    'hazard_resolved',
    'route_hazard_alert',
    'hazard_update'
);

CREATE TABLE notifications (
    id                  BIGSERIAL PRIMARY KEY,
    user_id             BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    hazard_id           BIGINT REFERENCES hazards(id) ON DELETE SET NULL,

    notification_type   notification_type NOT NULL,
    title               VARCHAR(150) NOT NULL,
    message             TEXT NOT NULL,
    is_read             BOOLEAN NOT NULL DEFAULT FALSE,

    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Users almost always query "my unread notifications, newest first" —
-- this composite index supports that access pattern directly.
CREATE INDEX idx_notifications_user_unread
    ON notifications (user_id, is_read, created_at DESC);
